/* IUnknown methods */
STDMETHODIMP CIIAObj::QueryInterface(REFIID riid, LPVOID* ppv)
{
    *ppv=nullptr;

    if(IID_IUnknown==riid ||
       IID_IOleWindow==riid ||
       IID_IOleInPlaceActiveObject==riid)
        *ppv=this;

    //AddRef any interface we'll return.
    if (nullptr!=*ppv)
    {
        static_cast<LPUNKNOWN>(*ppv)->AddRef();
        return NOERROR;
    }

    return ResultFromScode(E_NOINTERFACE);
}
CIIAObj::AddRef()
{
    return osl_atomic_increment( &m_refCount);
}
CIIAObj::Release()
{
    sal_Int32 nCount = osl_atomic_decrement( &m_refCount);
    if ( nCount == 0 )
        delete this;

    return nCount;
}
